def zigzagTraversal(grid: List[List[int]]) -> List[int]:
    result = []
    global_index = 0
    for i in range(len(grid)):
        if i % 2 == 0:
            # Traverse from left to right
            row_indices = range(len(grid[i]))
        else:
            # Traverse from right to left
            row_indices = range(len(grid[i]) - 1, -1, -1)
        for j in row_indices:
            if global_index % 2 == 0:
                result.append(grid[i][j])
            global_index += 1
    return result

def findValidPair(s: str) -> str:
    from collections import Counter
    counts = Counter(s)
    for i in range(len(s) - 1):
        a, b = s[i], s[i + 1]
        if a != b:
            if counts[a] == int(a) or counts[b] == int(b):
                return a + b
    return ""

