def minCost(n: int, cost: List[List[int]]) -> int:
    # We will use dynamic programming to solve the problem
    dp = [[[float('inf')] * 3 for _ in range(3)] for _ in range(n//2)]

    # Initialize the first pair of houses
    for j in range(3):
        for k in range(3):
            if j != k:
                dp[0][j][k] = cost[0][j] + cost[n - 1][k]

    # Fill the dp table
    for i in range(1, n // 2):
        for j in range(3):
            for k in range(3):
                if j != k:
                    dp[i][j][k] = min(dp[i][j][k], 
                        dp[i-1][l][m] + cost[i][j] + cost[n - 1 - i][k] 
                        for l in range(3) for m in range(3) if l != m)

    # Calculate the minimum cost from valid colorings
    min_cost = float('inf')
    for j in range(3):
        for k in range(3):
            if j != k:
                min_cost = min(min_cost, dp[n // 2 - 1][j][k])

    return min_cost + min(cost[n // 2]) if n % 2 == 0 else min_cost + min(cost[n // 2])

from typing import List

def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    online_status = [True] * numberOfUsers
    offline_until = [0] * numberOfUsers

    for event in events:
        event_type, timestamp, *args = event
        timestamp = int(timestamp)

        # Update online status before processing events
        for user_id in range(numberOfUsers):
            if not online_status[user_id] and timestamp >= offline_until[user_id]:
                online_status[user_id] = True

        if event_type == 'OFFLINE':
            user_id = int(args[0])
            online_status[user_id] = False
            offline_until[user_id] = timestamp + 60
        elif event_type == 'MESSAGE':
            mentions_string = args[0]
            mentioned_ids = mentions_string.split()
            for token in mentioned_ids:
                if token == 'ALL':
                    for i in range(numberOfUsers):
                        mentions[i] += 1
                elif token == 'HERE':
                    for i in range(numberOfUsers):
                        if online_status[i]:
                            mentions[i] += 1
                else:
                    user_id = int(token[2:])  # skip 'id'
                    mentions[user_id] += 1

    return mentions
